iki-admin/2024/05/07/4e8fcc3caecc822da9f71326f384f677_4085101205674063646.png","atributos":[{"clave":"Vinculo de almas gemelas","valores":["Lv.1","Lv.2","Lv.3","Lv.4","Lv.5"]},{"clave":"Aumento de daño","valores":["30%","37.5%","45%","52.5%","60%"]}]},{"nombre":"Espada de la unidad","tipo":"Técnica en cadena del bangbú","descripcion":"Invoca una gigantesca espada de la unificación con la que carga contra los enemigos de enfrente, lo que inflige una gran cantidad de daño físico y acumula Anomalía física.","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/05/07/b9daa065e187e79ff22d7185dba9c891_4290835035952596602.png","atributos":[{"clave":"Espada de la unidad","valores":["Lv.1","Lv.2","Lv.3","Lv.4","Lv.5","Lv.6","Lv.7","Lv.8","Lv.9","Lv.10"]},{"clave":"Multiplicador de daño","valores":["846%","930.6%","1015.2%","1099.8%","1184.4%","1269%","1353.6%","1438.2%","1522.8%","1607.3%"]},{"clave":"Multiplicador de Aturdimiento","valores":["121%","133.1%","145.2%","157.3%","169.4%","181.5%","193.6%","205.7%","217.8%","229.9%"]}]}]'::jsonb, null),
